32	static void show_only(lv_obj_t * show)
33	{
34	    lv_obj_t * boxes[] = {
35	        s_ota_ui.idle_box, s_ota_ui.offer_box, s_ota_ui.progress_box,
36	        s_ota_ui.ok_box, s_ota_ui.fail_box
37	    };
38	    size_t i;
39	    for(i = 0; i < sizeof(boxes) / sizeof(boxes[0]); i++) {
40	        if(boxes[i] == NULL) continue;
41	        if(show == boxes[i]) {
42	            if(lv_obj_has_flag(boxes[i], LV_OBJ_FLAG_HIDDEN))
43	                lv_obj_remove_flag(boxes[i], LV_OBJ_FLAG_HIDDEN);
44	        }
45	        else if(!lv_obj_has_flag(boxes[i], LV_OBJ_FLAG_HIDDEN)) {
46	            lv_obj_add_flag(boxes[i], LV_OBJ_FLAG_HIDDEN);
47	        }
48	    }
49	}
