51	static void on_install_btn_event(lv_event_t * e)
52	{
53	    lv_event_code_t code = lv_event_get_code(e);
54	    if(code == LV_EVENT_PRESSED) {
55	        const vg_ota_t *o = vg_model_get_ota();
56	        s_press_ms = lv_tick_get();
57	        s_pressed = true;
58	        snprintf(s_press_task, sizeof(s_press_task), "%s", o->task_id);
59	    }
60	    else if(code == LV_EVENT_PRESSING && s_pressed &&
61	            lv_tick_elaps(s_press_ms) >= VG_OTA_INSTALL_HOLD_MS) {
62	        const vg_ota_t *o = vg_model_get_ota();
63	        s_pressed = false;
64	        if(strcmp(s_press_task, o->task_id) != 0) return;
65	        if(s_ota_ui.of_hint) lv_label_set_text(s_ota_ui.of_hint, "正在检查安装条件...");
66	        vg_model_ota_accept();
67	    }
68	    else if(code == LV_EVENT_RELEASED || code == LV_EVENT_PRESS_LOST) {
69	        s_pressed = false;
70	    }
71	    else if(code == LV_EVENT_CLICKED) {
72	        if(s_ota_ui.of_hint) lv_label_set_text(s_ota_ui.of_hint, "请长按 2 秒确认安装");
73	    }
74	}
