100	static void refresh_ota(void * user)
101	{
102	    const vg_ota_t * o;
103	    char buf[48];
104	    LV_UNUSED(user);
105	    if(vg_nav_current() != VG_PAGE_OTA) return;
106	    if(s_ota_ui.root == NULL || !lv_obj_is_valid(s_ota_ui.root)) return;
107	
108	    o = vg_model_get_ota();
109	    if(o == NULL) return;
110	
111	    switch(o->state) {
112	        case VG_OTA_OFFER:
113	            lv_label_set_text(s_ota_ui.of_ver, o->version[0] ? o->version : "--");
114	            if(o->size_bytes) lv_snprintf(buf, sizeof(buf), "%lu B", (unsigned long)o->size_bytes);
115	            else lv_snprintf(buf, sizeof(buf), "%d MB", (int)o->size_mb);
116	            lv_label_set_text(s_ota_ui.of_size, buf);
117	            lv_label_set_text(s_ota_ui.of_note, o->note[0] ? o->note : "--");
118	            if(o->error[0] && s_ota_ui.of_hint) {
119	                lv_label_set_text(s_ota_ui.of_hint, o->error);
120	            }
121	            show_only(s_ota_ui.offer_box);
122	            break;
123	
124	        case VG_OTA_PROGRESS:
125	            lv_bar_set_value(s_ota_ui.bar, o->progress_pct, LV_ANIM_OFF);
126	            lv_snprintf(buf, sizeof(buf), "%d%% · 升级中，请勿断电",
127	                        (int)o->progress_pct);
128	            lv_label_set_text(s_ota_ui.bar_lab, buf);
129	            show_only(s_ota_ui.progress_box);
130	            break;
131	
132	        case VG_OTA_DONE_OK:
133	            show_only(s_ota_ui.ok_box);
134	            break;
135	
136	        case VG_OTA_DONE_FAIL:
137	            lv_label_set_text(s_ota_ui.fail_lab,
138	                              o->error[0] ? o->error : "升级失败");
139	            show_only(s_ota_ui.fail_box);
140	            break;
141	
142	        case VG_OTA_IDLE:
143	        default:
144	            show_only(s_ota_ui.idle_box);
145	            break;
146	    }
147	}
