static int read_mmc_register(int fd, uint32_t opcode, void *buf)
{
  struct mmc_ioc_cmd cmd;
  int ret;

  memset(&cmd, 0, sizeof(cmd));
  cmd.opcode = opcode;
  cmd.blksz = 512;
  cmd.blocks = 1;
  cmd.data_ptr = (uint64_t)(uintptr_t)buf;

  ret = ioctl(fd, MMC_IOC_CMD, (unsigned long)(uintptr_t)&cmd);
  if (ret < 0)
    {
      return -errno;
    }

  return 0;
}

